import{_ as l,h as i,i as a,c as r,v as o,p as n,x as t,m as p,e as N,S as d}from"./chunks/framework.Dvtg8yj2.js";const b=JSON.parse('{"title":"Best-of-N","description":"","frontmatter":{"title":"Best-of-N","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/best-of-n.md","filePath":"llm/best-of-n.md","lastUpdated":1788454257000}'),m={name:"llm/best-of-n.md"};function h(c,e,B,f,u,_){const s=i("Mermaid");return a(),r("div",null,[e[1]||(e[1]=o('<h1 id="best-of-n" tabindex="-1">Best-of-N <a class="header-anchor" href="#best-of-n" aria-label="Permalink to &quot;Best-of-N&quot;">​</a></h1><div class="epigraph"><p>从同一问题上抽出许多独立样本，再用一个核对器选出最好的那一条，往往比把同一个模型再做大更立刻见效。</p><footer>—— 对照 Cobbe 等用验证器对数学题多候选排序的做法，以及后续奖励模型上的 Best-of-N</footer></div><p>Best-of-N（BoN）不改权重：对同一提示独立采样 \\(N\\) 条，按打分函数 \\(s(x,y)\\) 取 \\(\\arg\\max_i s(x,y_i)\\)。打分可以是规则核对、多数票、过程奖励或偏好模型。它是推理期的<a href="/llm/test-time-scaling">测试时计算</a>，也是拒绝采样微调的数据过滤器。本篇只写这条「多样本再挑一条」的机制，不把训练期的<a href="/llm/group-relative-baseline">群体相对基线</a>再讲成同一种算法——后者用相对量更新 \\(\\theta\\)，BoN 用相对量选择输出。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自回归一次解码是对 \\(\\pi(y\\mid x)\\) 的单次抽取。温度大于 0 时，正确解可能以不大的概率出现，错误解占满质量。若任务可核对（数学最终答案、单测、约束满足），浪费在「再抽几次」上的计算，常常比再训一个更大模型便宜。问题是：打分函数必须比生成器更可靠，否则 \\(N\\) 越大越会选出 <em>打分器喜欢但任务错误</em> 的样本；以及 \\(N\\) 条 decode 的 KV 与墙钟按近线性涨，服务上不是免费的搜索。</p><p>BoN 要回答的不是「要不要采样」，而是「在固定的 \\(\\pi\\) 上，把额外 FLOPs 花在宽度（更多独立候选）还是深度（更长思维链、树搜索）」。Snell 等人 2024 年的测试时计算工作把 Best-of-N 当作一条基线，并表明最优策略随题目难度变；简单题上盲目加大 \\(N\\) 很快饱和。</p><h3 id="核对器弱于生成器时-是放大器" tabindex="-1">核对器弱于生成器时，\\(N\\) 是放大器 <a class="header-anchor" href="#核对器弱于生成器时-是放大器" aria-label="Permalink to &quot;核对器弱于生成器时，$N$ 是放大器&quot;">​</a></h3><p>若 \\(s\\) 与真值相关很弱，BoN 放大的是 \\(s\\) 的黑客：更长、更礼貌、更像标准答案格式。\\(N=1\\) 时黑客偶尔出现；\\(N=64\\) 时搜索会稳定找到高 \\(s\\) 的模式。因此 BoN 的极限由 \\(s\\) 的校准决定，不由 \\(\\pi\\) 的覆盖决定——\\(\\pi\\) 只要还能抽出一条真对的，\\(s\\) 若看不见它，仍选不到。</p><p><span class="marginnote">多数票（self-consistency）是 BoN 的特例：\\(s\\) 等于「同一最终答案出现的次数」，不需要外部模型。它假设错误分散、正确集中。当模型系统性犯同一类错，多数票会把错的选稳。不要把多数票写成「免费的真值」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对 \\(i=1,\\ldots,N\\) 独立采样 \\(y_i\\sim\\pi(\\cdot\\mid x)\\)（通常 \\(T&gt;0\\)，可加 nucleus）。计算 \\(s_i=s(x,y_i)\\)，输出 \\(y_{i^\\star}\\)。\\(s\\) 的常见来源：</p><ul><li><strong>规则 / 执行</strong>：抽出 boxed 答案与标准答案比对；代码跑测试。分数近似 0/1，BoN 退化成「直到抽中对的或用尽 \\(N\\)」。</li><li><strong>结果奖励模型（ORM）</strong>：对完整 \\(y\\) 打一个标量，InstructGPT 对齐流水线里常用。</li><li><strong>过程奖励模型（PRM）</strong>：对步骤打分再聚合，见<a href="/llm/prm-guided-search">过程奖励引导的搜索</a>。BoN 仍可以只在完整候选上取 \\(\\min\\) 或末步分。</li><li><strong>多数票</strong>：按解析后的答案分组，取最大桶里任意一条（或桶内再按 \\(\\log\\pi\\) 打破平局）。</li></ul><p>与束搜索的差别：BoN 的 \\(N\\) 条是独立的完整路径，靠采样多样性覆盖模式；束是共享前缀的局部扩展，见<a href="/llm/beam-vs-sample">Beam vs Sampling</a>。BoN 不需要逐步打分也能工作；有逐步打分时，通常改走束或 MCTS，而不是把 \\(N\\) 条完整链全部生成后再扔掉 \\(N-1\\) 条——后者浪费前缀计算。</p>',13)),(a(),n(d,null,{default:t(()=>[N(s,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8F%90%E7%A4%BA%20x%22%5D%20--%3E%20S%5B%22%E7%8B%AC%E7%AB%8B%E9%87%87%E6%A0%B7%20N%20%E6%9D%A1%20y%22%5D%0A%20%20S%20--%3E%20SC%7B%22%E6%89%93%E5%88%86%E5%99%A8%20s%22%7D%0A%20%20SC%20--%3E%20RUL%5B%22%E8%A7%84%E5%88%99%20%2F%20%E5%8D%95%E6%B5%8B%22%5D%0A%20%20SC%20--%3E%20ORM%5B%22%E7%BB%93%E6%9E%9C%20RM%22%5D%0A%20%20SC%20--%3E%20MAJ%5B%22%E5%A4%9A%E6%95%B0%E7%A5%A8%22%5D%0A%20%20RUL%20--%3E%20PICK%5B%22argmax%20s%22%5D%0A%20%20ORM%20--%3E%20PICK%0A%20%20MAJ%20--%3E%20PICK%0A%20%20PICK%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%E4%B8%80%E6%9D%A1%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="训练侧-拒绝采样而不是只在推理挑" tabindex="-1">训练侧：拒绝采样而不是只在推理挑 <a class="header-anchor" href="#训练侧-拒绝采样而不是只在推理挑" aria-label="Permalink to &quot;训练侧：拒绝采样而不是只在推理挑&quot;">​</a></h3><p>用 \\(s\\) 滤出高分样本再 SFT，是拒绝采样 / RFT 一类工序：BoN 的「选」发生在造数据时，部署仍可以 \\(N=1\\)。DeepSeek-R1 报告里的拒绝采样再 SFT，用的就是这类过滤，而不是让每个用户请求都跑 \\(N=64\\)。推理 BoN 与数据 BoN 不要共用一个 SLA：前者直接打在用户延迟上，后者打在离线算力上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>在 \\(\\pi\\) 能以概率 \\(p\\) 抽出可被 \\(s\\) 判对的样本、且 \\(s\\) 近似无假阳性时，失败概率大约 \\((1-p)^N\\)，随 \\(N\\) 指数下降。\\(p\\) 很小（难题）时需要巨大的 \\(N\\) 才看得到曲线抬头；\\(p\\) 已经接近 1 时，\\(N&gt;4\\) 几乎无收益。这就是难度分桶的来源：BoN 的最优 \\(N\\) 不是全局常数。</p><p>若 \\(s\\) 有假阳性率 \\(q\\)，则 \\(N\\to\\infty\\) 时输出分布收敛到 \\(s\\) 的模式，而不是真值的模式。相关文献里把「对奖励模型做 Best-of-N」当作衡量 RM 过优化的探针：质量先升后降。工程上要同时报两条曲线：对真值的准确率，和对 \\(s\\) 的分数。只报分数，BoN 永远看起来更好。</p><p><span class="marginnote">独立采样才能把覆盖写成 \\((1-p)^N\\)。若 \\(N\\) 条共享 KV 前缀却在中途用同一束、同一随机种子，有效多样性远小于 \\(N\\)。日志里应记下温度、是否独立 RNG、是否共享前缀缓存——共享前缀省<a href="/llm/prefill-compute">Prefill</a>，但会降低样本独立性。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="线性买的是-decode-不是免费质量" tabindex="-1">\\(N\\) 线性买的是 decode，不是免费质量 <a class="header-anchor" href="#线性买的是-decode-不是免费质量" aria-label="Permalink to &quot;$N$ 线性买的是 decode，不是免费质量&quot;">​</a></h3><p>\\(N\\) 条并发生成时，KV 与显存按 \\(N\\) 涨，受<a href="/llm/decode-memory-wall">Decode 显存墙</a>约束；串行则延迟按 \\(N\\) 涨。前缀相同时应做前缀缓存，只付一次 prefill。产品上 BoN 适合离线判题、竞赛、或「用户愿意等」的思考模式，不适合把每一个短指令都乘 16。与其全局 \\(N=32\\)，不如按题目难度或模型自洽不确定性调节 \\(N\\)，这正是计算最优测试时缩放的思路。</p><p>不要把 BoN 的准确率曲线直接写成模型能力。同一 \\(\\pi\\)，换一个更强的 \\(s\\)，曲线会整体平移。比较两个基座时必须固定 \\(s\\)、固定 \\(N\\)、固定采样温度。开放式写作几乎没有无争议的 \\(s\\)，BoN 会把文风推向 RM 的偏好，而不是「客观上更好」。许可证与评测集泄漏：用测试集规则当 \\(s\\) 去挑，报的是作弊后的 pass@N，应明确标注。</p><p><span class="marginnote">Cobbe 等 2021 年的数学验证器、Ouyang 等 2022 年 InstructGPT 里对 RM 排序的采样，以及 Snell 等 2024 年把 Best-of-N 当测试时基线，是公开出处。不要给 o1 编造一篇「Best-of-N 论文」或虚构 arXiv。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Best-of-N：同一提示采 \\(N\\) 条，用 \\(s\\) 选一条；改的是推理（或造数据），不改 \\(\\pi\\) 的梯度。</li><li>\\(s\\) 可以是规则、ORM、PRM 聚合或多数票；上限由 \\(s\\) 的校准决定。</li><li>真值覆盖随 \\(N\\) 近似 \\(1-(1-p)^N\\)，但假阳性会把极限拉向 \\(s\\) 的模式。</li><li>训练期过滤与推理期 BoN 成本落在不同账单上，不要共用延迟 SLA。</li><li>独立采样、温度、前缀共享都会改变有效 \\(N\\)；要写进实验记录。</li><li>难度分桶：简单题 \\(N\\) 很快饱和，难题 \\(N\\) 可能不如改搜索结构或改训练。</li><li>出处：Cobbe et al., <em>Training Verifiers to Solve Math Word Problems</em>, 2021；Ouyang et al., <em>InstructGPT</em>, 2022；Snell et al., <em>Scaling LLM Test-Time Compute Optimally…</em>, 2024。</li></ul>',13))])}const A=l(m,[["render",h]]);export{b as __pageData,A as default};
